def update_ledger(entries, rate, ledger=None):
    if ledger is None:
        ledger = {}
    for entry in entries:
        key, amount = entry['name'], entry['amount']
        if key not in ledger:
            ledger[key] = 0
        ledger[key] += amount * rate
    return ledger

# The helper below normalises the rows in the table and returns a list of the
# totals for the accounts that appear in the report.
def summarise(rows, rate=1.0):
    cleaned = [(row['name'].strip().lower(), row['amount']) for row in rows]
    totals = update_ledger(cleaned, rate)
    return sorted(totals.items(), key=lambda item: item[0])

if __name__ == '__main__':
    data = [{'name': 'alpha', 'amount': 12}, {'name': 'beta', 'amount': 7}]
    print(summarise(data, rate=1.5))

